def effective_rate(original_minor: int, base_minor: int) -> Fraction | None:
    """Re-derive the recorded rate from the saved original/base pair.

    Returns ``None`` when the original amount is zero (no rate is
    definable).  The rate is the rate *already recorded* on the books:
    it never consults a current or externally supplied exchange rate.
    """
    if original_minor == 0:
        return None
    # original * rate * (scale_base / scale_orig) = base, but both
    # arguments are integer minor units of possibly different scales;
    # the caller passes same-unit pair here (see model.LEdgerFact).
    return Fraction(base_minor, original_minor)

